# Animation v2 · VM (chương mới) Trước Compose: animation trong hệ View, đối chiếu với Compose
# Nguồn: Android Animations by Tutorials Ch.1 (ValueAnimator, interpolator, ObjectAnimator), Ch.3 (XML: anim vs animator, cảnh báo view
# animation, AnimatorSet), Ch.4 (overridePendingTransition, navigation enter/exit/popEnter/popExit), Ch.5 (Transition framework);
# "Property Animation overview" (views-prop: elapsed fraction → TimeInterpolator → TypeEvaluator; mặc định 300 ms; view animation chỉ đổi chỗ vẽ).

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    m = lambda k, vi, en=None: a('m.vframe.' + k, vi, en)
    m('title', 'Một frame của animator: phân số thời gian → interpolator → evaluator', 'One animator frame: time fraction → interpolator → evaluator')
    m('overview', 'Một nút dịch ngang 0 → 40 px trong 40 ms với AccelerateDecelerateInterpolator (ví dụ của tài liệu Property Animation). Ba cách: `ObjectAnimator` trên `translationX` (property animation); `TranslateAnimation` (view animation cũ); và Compose với `animateFloatAsState`. Theo dõi phân số thời gian, phân số sau interpolator, giá trị, và nút thật sự nằm ở đâu.', 'A button moves horizontally 0 → 40 px in 40 ms with an AccelerateDecelerateInterpolator (the Property Animation docs\' example). Three ways: an `ObjectAnimator` on `translationX` (property animation); a `TranslateAnimation` (the old view animation); and Compose with `animateFloatAsState`. Watch the time fraction, the fraction after the interpolator, the value, and where the button really is.')
    m('wrapup', 'Mọi hệ animation đều tính cùng một chuỗi mỗi frame: phân số thời gian đã trôi → hàm làm cong thời gian (TimeInterpolator / Easing) → hàm tính giá trị theo kiểu (TypeEvaluator / TwoWayConverter). Khác nhau ở chỗ giá trị được ghi vào đâu: property animation đổi thuộc tính THẬT của View; view animation cũ chỉ đổi chỗ VẼ, nên vùng chạm nằm lại chỗ cũ; Compose ghi vào state và phase nào đọc thì phase đó chạy lại.', 'Every animation system computes the same chain each frame: elapsed time fraction → a function bending time (TimeInterpolator / Easing) → a function computing the typed value (TypeEvaluator / TwoWayConverter). The difference is where the value is written: property animation changes the View\'s REAL property; the old view animation only changes where it is DRAWN, so the touch area stays behind; Compose writes to state, and whichever phase reads it re-runs.')
    m('simp.1', 'Thời lượng 40 ms và bốn mốc 10 ms là ví dụ của tài liệu, không phải nhịp frame thật; giá trị làm tròn tới 0,1 px.', 'The 40 ms duration and the four 10 ms marks are the docs\' example, not real frame timing; values are rounded to 0.1 px.')
    m('simp.2', 'Phân số sau interpolator tính bằng công thức AccelerateDecelerate (cos((t+1)π)/2 + 0,5); Compose không có easing trùng tên, mô hình dùng cùng công thức để so sánh.', 'The interpolated fraction uses the AccelerateDecelerate formula (cos((t+1)π)/2 + 0.5); Compose has no easing with that name, so the model uses the same formula for comparison.')
    m('ctl.hint', 'So cột "nút thật ở" giữa ObjectAnimator và TranslateAnimation.', 'Compare the "button really at" column between ObjectAnimator and TranslateAnimation.')
    for k, vi, en in [('property', 'ObjectAnimator trên translationX', 'ObjectAnimator on translationX'), ('viewanim', 'TranslateAnimation (view animation cũ)', 'TranslateAnimation (old view animation)'), ('compose', 'animateFloatAsState của Compose', 'Compose animateFloatAsState')]:
        m('ctl.which.' + k, vi, en)
    m('ctl.which', 'API dùng', 'API used')
    m('diagramTitle', 'Đồng hồ, interpolator, evaluator, đích ghi giá trị', 'Clock, interpolator, evaluator, where the value is written')
    m('diagramDesc', 'Đồng hồ cho phân số thời gian; interpolator làm cong nó; evaluator tính giá trị; giá trị được ghi vào View, vào phép vẽ, hoặc vào state', 'The clock gives the time fraction; the interpolator bends it; the evaluator computes the value; the value is written to the View, to the drawing, or to state')
    for k, vi, en in [('clock', 'Phân số thời gian', 'Elapsed fraction'), ('interp', 'Làm cong thời gian', 'Interpolator / Easing'), ('eval', 'Tính giá trị', 'Evaluator / Converter'), ('target', 'Nơi ghi giá trị', 'Where it is written')]:
        m('n.' + k, vi, en)
    for k, vi, en in [('elapsed', 'Phân số thời gian (%)', 'Elapsed fraction (%)'), ('interp', 'Sau interpolator (%)', 'After interpolator (%)'), ('value', 'Giá trị (px ×10)', 'Value (px ×10)')]:
        m('met.' + k, vi, en)
    for k, vi, en in [('drawn', 'Nút được vẽ ở', 'Button drawn at'), ('real', 'Nút thật ở (vùng chạm)', 'Button really at (touch area)'), ('writes', 'Giá trị ghi vào', 'Value written to')]:
        m('st.' + k, vi, en)
    S = [
        ('intro.property', 'Property animation với ObjectAnimator', 'Property animation with ObjectAnimator', '`duration = 40`, `interpolator = AccelerateDecelerateInterpolator()`. ObjectAnimator là lớp con của ValueAnimator, tự gọi setter của thuộc tính thay cho update listener.', '`duration = 40`, `interpolator = AccelerateDecelerateInterpolator()`. ObjectAnimator is a subclass of ValueAnimator that calls the property setter for you instead of an update listener.'),
        ('intro.viewanim', 'View animation cũ với TranslateAnimation', 'Old view animation with TranslateAnimation', 'View animation cũ (gói `android.view.animation`), thường viết trong `res/anim` và nạp bằng `AnimationUtils.loadAnimation`.', 'The old view animation (package `android.view.animation`), usually written in `res/anim` and loaded with `AnimationUtils.loadAnimation`.'),
        ('intro.compose', 'Compose với animateFloatAsState', 'Compose with animateFloatAsState', 'Cùng thời lượng, cùng đường cong (tự định nghĩa bằng `Easing { … }`); giá trị đọc trong `Modifier.offset { }`.', 'The same duration and curve (self-defined with `Easing { … }`); the value is read in `Modifier.offset { }`.'),
        ('tick', 't = {ms} ms: thời gian {e}%, sau interpolator {i}%, giá trị {v} px', 't = {ms} ms: time {e}%, after interpolator {i}%, value {v} px', 'Phân số thời gian = thời gian đã trôi / thời lượng. Interpolator làm cong nó (đầu chậm, giữa nhanh, cuối chậm). Evaluator tính giá trị = đầu + phân số × (cuối − đầu).', 'Time fraction = elapsed time / duration. The interpolator bends it (slow start, fast middle, slow end). The evaluator computes value = start + fraction × (end − start).'),
        ('write.property', 'Ghi vào View: setTranslationX({v}) → invalidate()', 'Written to the View: setTranslationX({v}) → invalidate()', 'Thuộc tính THẬT của View đổi, nên cả hình vẽ lẫn vùng chạm đều dời theo. Với View, hệ thống gọi `invalidate()` khi thuộc tính đổi.', 'The View\'s REAL property changes, so both the drawing and the touch area move. For a View, the system calls `invalidate()` when the property changes.'),
        ('write.viewanim', 'Chỉ dời hình vẽ tới {v} px', 'Only the drawing moves to {v} px', 'View animation chỉ đổi CHỖ VẼ; vị trí của View không đổi.', 'A view animation only changes WHERE IT IS DRAWN; the View\'s position does not change.'),
        ('write.compose', 'Ghi vào state; offset { } đọc ở bước đặt', 'Written to state; offset { } reads it at placement', 'Giá trị là snapshot state; vì nó chỉ được đọc trong lambda của `Modifier.offset { }`, mỗi frame chỉ layout (bước đặt) và draw chạy lại (chương B7).', 'The value is snapshot state; since it is only read inside the `Modifier.offset { }` lambda, each frame only layout (placement) and draw re-run (chapter B7).'),
        ('tap.property', 'Chạm vào chỗ nút đang hiện: trúng', 'Tap where the button appears: hit', 'Vùng chạm đi theo thuộc tính thật.', 'The touch area follows the real property.'),
        ('tap.viewanim', 'Chạm vào chỗ nút đang hiện: TRƯỢT', 'Tap where the button appears: MISS', 'Nút vẫn ở 0 px; chỉ ảnh của nó ở 40 px. Đây là cảnh báo của cả tài liệu và sách AAT Ch.3.', 'The button is still at 0 px; only its image is at 40 px. This is the warning in both the docs and AAT Ch.3.'),
        ('tap.compose', 'Đã ở 40 px', 'Now at 40 px', 'Cùng chuỗi tính toán, chỉ khác tên: Easing thay TimeInterpolator, TwoWayConverter + AnimationVector thay TypeEvaluator (chương C2).', 'The same computation chain with different names: Easing for TimeInterpolator, TwoWayConverter + AnimationVector for TypeEvaluator (chapter C2).'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('chain', 'Tài liệu Property Animation: ValueAnimator tính phân số thời gian, gọi TimeInterpolator lấy phân số đã nội suy, rồi gọi TypeEvaluator tính giá trị. Ví dụ của tài liệu: ở t = 10 ms trên 40 ms, phân số 0,25 thành khoảng 0,15. [[src:views-prop]]', 'The Property Animation docs: ValueAnimator computes the elapsed fraction, calls the TimeInterpolator for the interpolated fraction, then the TypeEvaluator for the value. The docs\' example: at t = 10 ms of 40 ms, the fraction 0.25 becomes about 0.15. [[src:views-prop]]'),
        ('viewanim', 'Tài liệu: view animation chỉ đổi chỗ View được vẽ, không đổi chính View; nút được vẽ đúng nhưng vùng bấm không đổi. [[src:views-prop]] [[src:book-aat]]', 'The docs: view animation only modifies where the View is drawn, not the View itself; the button draws correctly but the clickable location does not change. [[src:views-prop]] [[src:book-aat]]'),
        ('phase', 'Cầu nối X1: đọc ở lambda của offset { } thì không recompose mỗi frame (chương B7). [[src:cp-phases]]', 'Bridge X1: reading inside the offset { } lambda does not recompose every frame (chapter B7). [[src:cp-phases]]')]:
        m('co.' + k, vi, en)
    a('cap.vframe', 'Từ trái sang phải: phân số thời gian, interpolator làm cong nó, evaluator tính giá trị, và nơi giá trị được ghi (thuộc tính View, phép vẽ, hoặc state).', 'Left to right: the time fraction, the interpolator bending it, the evaluator computing the value, and where the value is written (a View property, the drawing, or state).')

    C = 'vm'
    a(C + '.title', 'Trước Compose: animation trong hệ View', 'Before Compose: animation in the View system')
    a(C + '.essence',
      'Hệ View có ba lớp: view animation cũ (`res/anim`, chỉ đổi chỗ vẽ), property animation (`ValueAnimator`, `ObjectAnimator`, `AnimatorSet`, `res/animator`, đổi thuộc tính thật) và Transition framework (animate thay đổi của cả một ViewGroup, chuyển màn hình).\nMỗi frame của animator: phân số thời gian → TimeInterpolator → TypeEvaluator; Compose giữ đúng chuỗi đó với Easing và TwoWayConverter.\nĐối chiếu giúp đọc code cũ và chọn API Compose tương ứng, không phải để chép từng dòng.',
      'The View system has three layers: the old view animation (`res/anim`, only changes where things are drawn), property animation (`ValueAnimator`, `ObjectAnimator`, `AnimatorSet`, `res/animator`, changes real properties) and the Transition framework (animates changes to a whole ViewGroup, screen transitions).\nEach animator frame: time fraction → TimeInterpolator → TypeEvaluator; Compose keeps exactly that chain with Easing and TwoWayConverter.\nThe mapping helps you read old code and pick the matching Compose API, not copy it line by line.')
    a(C + '.goal.g1', 'Đã chạy mốc thời gian đầu tiên', 'Ran the first time mark')
    a(C + '.goal.g2', 'Đã chạy một API tới cuối', 'Ran one API to the end')
    a(C + '.sim.animation.vframe', 'Một frame của animator', 'One animator frame')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'predict', 'Một nút được dời sang phải 200 px bằng `TranslateAnimation` với `fillAfter = true` (giữ nguyên ở cuối). Chạm vào chỗ nút đang hiện có kích hoạt nó không?', 'A button is moved 200 px to the right with a `TranslateAnimation` and `fillAfter = true` (stays at the end). Does tapping where the button appears trigger it?')
    B(C, S, 1, 'ans', 'Không. View animation chỉ dời HÌNH của View (bitmap), còn View thật vẫn ở chỗ cũ, nên vùng bấm nằm lại. Sách AAT Ch.3 và tài liệu chính thức đều cảnh báo điểm này; property animation (`ObjectAnimator` trên `translationX`) thì đổi thuộc tính thật. [[src:book-aat]] [[src:views-prop]]', 'No. A view animation only moves the View\'s IMAGE (its bitmap), while the real View stays where it was, so the clickable area stays behind. Both AAT Ch.3 and the official docs warn about this; property animation (`ObjectAnimator` on `translationX`) changes the real property. [[src:book-aat]] [[src:views-prop]]')

    S = 'animators'
    a(C + '.sec.%s.title' % S, 'ValueAnimator, ObjectAnimator, interpolator', 'ValueAnimator, ObjectAnimator, interpolators')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'AAT Ch.1 bắt đầu bằng cách đơn giản nhất: `ValueAnimator.ofFloat(0f, 1f)`, `duration = 1000`, và trong `addUpdateListener` lấy `animatedValue` gán cho `alpha` của poster. Rồi tới `ObjectAnimator.ofFloat(view, "translationY", …)`: lớp con của ValueAnimator, tự gọi setter của thuộc tính nên không cần listener; hợp khi chỉ đổi một thuộc tính. Muốn gộp nhiều animator (chạy cùng lúc hay nối nhau), dùng `AnimatorSet`; sách giới thiệu nó ở Ch.3 dưới dạng thẻ `<set>` trong XML. [[src:book-aat]]', 'AAT Ch.1 starts with the simplest way: `ValueAnimator.ofFloat(0f, 1f)`, `duration = 1000`, and in `addUpdateListener` take `animatedValue` and assign it to the poster\'s `alpha`. Then `ObjectAnimator.ofFloat(view, "translationY", …)`: a ValueAnimator subclass that calls the property setter itself, so no listener is needed; good when only one property changes. To combine several animators (together or in sequence), use `AnimatorSet`; the book introduces it in Ch.3 as a `<set>` tag in XML. [[src:book-aat]]')
    B(C, S, 2, 'p', 'Sách dành một mục cho interpolator: Linear (đều, "như máy"; sách khuyên tránh nếu muốn tự nhiên), Accelerate, Decelerate, AccelerateDecelerate, Overshoot (vượt quá đích rồi về), Anticipate (lùi lại trước khi đi, như ná cao su), Bounce (nảy ở cuối). Ghi chú của sách: interpolator đổi CẢM GIÁC của animation dù giá trị đầu và cuối giữ nguyên. [[src:book-aat]]', 'The book has a section on interpolators: Linear (even, "robotic"; the book advises avoiding it for natural motion), Accelerate, Decelerate, AccelerateDecelerate, Overshoot (goes past the target and back), Anticipate (pulls back before going, like a slingshot), Bounce (bounces at the end). The book\'s note: an interpolator changes the FEEL of an animation even when the start and end values stay the same. [[src:book-aat]]')
    B(C, S, 3, 'p', 'Tài liệu Property Animation mô tả chính xác điều xảy ra mỗi frame: ValueAnimator tính phân số thời gian đã trôi (0 là 0%, 1 là 100%); gọi TimeInterpolator để có phân số đã nội suy; rồi gọi TypeEvaluator để tính giá trị từ phân số đó, giá trị đầu và cuối. Nếu đối tượng là View, hệ thống gọi `invalidate()` khi thuộc tính đổi. Thời lượng mặc định là 300 ms (cùng con số với `AnimationConstants.DefaultDurationMillis` của Compose ở chương C2). Mô phỏng ngay dưới dùng đúng ví dụ 40 ms của tài liệu. [[src:views-prop]]', 'The Property Animation docs describe exactly what happens each frame: ValueAnimator computes the elapsed time fraction (0 is 0%, 1 is 100%); calls the TimeInterpolator for the interpolated fraction; then calls the TypeEvaluator to compute the value from that fraction and the start and end values. If the object is a View, the system calls `invalidate()` when the property changes. The default duration is 300 ms (the same number as Compose\'s `AnimationConstants.DefaultDurationMillis` in chapter C2). The simulation just below uses the docs\' exact 40 ms example. [[src:views-prop]]')

    S = 'xml'
    a(C + '.sec.%s.title' % S, 'XML: res/anim và res/animator', 'XML: res/anim and res/animator')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'AAT Ch.3: animation viết bằng XML dễ dùng lại. Thư mục `anim` chứa khai báo view animation (tween: translate, scale, alpha, rotate), nạp bằng `AnimationUtils.loadAnimation`; thư mục `animator` chứa khai báo `ValueAnimator`/`ObjectAnimator`/`set`, nạp bằng `AnimatorInflater.loadAnimator`. Sách nêu rõ nhược điểm của view animation: nó chỉ dời pixel của View, nên một nút sau khi "dời" không bấm được ở chỗ mới; Google khuyên không dùng nó cho phần tử tương tác. Kết luận của sách: Animator API an toàn và hiện đại hơn. [[src:book-aat]] [[src:views-prop]]', 'AAT Ch.3: animations written in XML are easy to reuse. The `anim` folder holds view animation declarations (tweens: translate, scale, alpha, rotate), loaded with `AnimationUtils.loadAnimation`; the `animator` folder holds `ValueAnimator`/`ObjectAnimator`/`set` declarations, loaded with `AnimatorInflater.loadAnimator`. The book spells out the view animation drawback: it only moves the View\'s pixels, so a button that was "moved" cannot be tapped at its new place; Google advises against it for interactive elements. The book\'s conclusion: the Animator APIs are safer and more modern. [[src:book-aat]] [[src:views-prop]]')
    B(C, S, 2, 'p', 'Liên hệ với chương CV: file `<animated-vector>` dùng chính các `objectAnimator`/`set` trong `res/animator` để nhắm vào từng phần tử của vector; Compose đọc chúng và đổi thành keyframes trên một Transition. [[src:an-animator-src]]', 'Link to chapter CV: an `<animated-vector>` file uses those very `objectAnimator`/`set` declarations from `res/animator` to target each element of the vector; Compose reads them and turns them into keyframes on a Transition. [[src:an-animator-src]]')

    S = 'screens'
    a(C + '.sec.%s.title' % S, 'Chuyển màn hình và Transition framework', 'Screen transitions and the Transition framework')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'AAT Ch.4: chuyển Activity bằng `overridePendingTransition(enterAnim, exitAnim)` ngay sau `startActivity` (và sau `finish` khi quay lại), với các file `res/anim` kết hợp `scale`, `translate`, `alpha`; với Navigation component, đặt `enterAnim`, `exitAnim`, `popEnterAnim`, `popExitAnim` cho action. AAT Ch.5: Transition framework làm việc trên CẢ một ViewGroup, animate thay đổi hiển thị của các con hoặc thay đổi cấu trúc, thay vì từng View; Fragment có `enterTransition`, `exitTransition`, `reenterTransition`, `returnTransition`; `TransitionSet` gộp nhiều transition, `addTarget`/`removeTarget` chọn View; `MaterialSharedAxis` của thư viện Material cho kết quả nhanh. Sách dặn dùng bản AndroidX của Transition framework thay vì bản platform. Ch.6 (shared element) đã đối chiếu ở chương SE. [[src:book-aat]]', 'AAT Ch.4: Activity transitions with `overridePendingTransition(enterAnim, exitAnim)` right after `startActivity` (and after `finish` when going back), using `res/anim` files combining `scale`, `translate`, `alpha`; with the Navigation component, set `enterAnim`, `exitAnim`, `popEnterAnim`, `popExitAnim` on the action. AAT Ch.5: the Transition framework works on a WHOLE ViewGroup, animating visibility changes of its children or structural changes, rather than single Views; Fragments have `enterTransition`, `exitTransition`, `reenterTransition`, `returnTransition`; `TransitionSet` combines transitions, `addTarget`/`removeTarget` pick Views; the Material library\'s `MaterialSharedAxis` gives quick wins. The book says to use the AndroidX version of the Transition framework rather than the platform one. Ch.6 (shared elements) was compared in chapter SE. [[src:book-aat]]')

    S = 'map'
    a(C + '.sec.%s.title' % S, 'Bảng đối chiếu View → Compose', 'Mapping table View → Compose')
    a(C + '.sec.%s.badge' % S, 'guideline')
    B(C, S, 1, 'p', '`ValueAnimator` + update listener → `animate*AsState` hoặc `Animatable` (C1, C6). `ObjectAnimator(view, "alpha")` → đọc state trong `Modifier.graphicsLayer { alpha = … }` (C7). `TimeInterpolator` → `Easing`; `TypeEvaluator` → `TwoWayConverter` + `AnimationVector` (C2). `AnimatorSet.playTogether` → nhiều con của một `Transition` (C3); `playSequentially` → gọi suspend nối tiếp (C6). `repeatCount`/`repeatMode` → `repeatable`/`infiniteRepeatable` (IF). Transition framework trên ViewGroup → `AnimatedVisibility`, `animateContentSize`, `animateItem` (C4, C5). `overridePendingTransition`/nav anim → `AnimatedContent` hoặc `enterTransition`/`exitTransition` của NavHost. `transitionName` → key của `sharedElement` (SE). Đây là ánh xạ ý niệm do site tự lập để định hướng, không phải bảng tương đương chính thức; hành vi chi tiết khác nhau. [[src:book-aat]] [[src:an-choose]]', '`ValueAnimator` + update listener → `animate*AsState` or `Animatable` (C1, C6). `ObjectAnimator(view, "alpha")` → read state in `Modifier.graphicsLayer { alpha = … }` (C7). `TimeInterpolator` → `Easing`; `TypeEvaluator` → `TwoWayConverter` + `AnimationVector` (C2). `AnimatorSet.playTogether` → several children of one `Transition` (C3); `playSequentially` → sequential suspend calls (C6). `repeatCount`/`repeatMode` → `repeatable`/`infiniteRepeatable` (IF). The Transition framework on a ViewGroup → `AnimatedVisibility`, `animateContentSize`, `animateItem` (C4, C5). `overridePendingTransition`/nav anims → `AnimatedContent` or NavHost\'s `enterTransition`/`exitTransition`. `transitionName` → the `sharedElement` key (SE). This is a conceptual mapping the site made for orientation, not an official equivalence table; detailed behaviour differs. [[src:book-aat]] [[src:an-choose]]')
    B(C, S, 1, 'kind', 'analogy')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp khi chuyển từ View', 'Common bugs when moving from Views')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Nút đã "trượt" sang chỗ mới nhưng bấm không ăn.', 'The button "slid" to its new place but tapping does nothing.')
    B(C, S, 1, 'cause', 'Dùng view animation (`TranslateAnimation`/`res/anim`), chỉ dời hình vẽ.', 'A view animation (`TranslateAnimation`/`res/anim`) was used; it only moves the drawing.')
    B(C, S, 1, 'fix', 'Dùng property animation (`ObjectAnimator`, `view.animate().translationX(…)`), hoặc trong Compose dùng `Modifier.offset { }`. [[src:views-prop]] [[src:book-aat]]', 'Use property animation (`ObjectAnimator`, `view.animate().translationX(…)`), or in Compose use `Modifier.offset { }`. [[src:views-prop]] [[src:book-aat]]')
    B(C, S, 2, 'bug', 'Chép thói quen "giữ một ValueAnimator và gọi start() trong click" sang Compose: tạo animator trong thân composable, mỗi lần recompose lại tạo cái mới.', 'Carrying over the habit of "keep a ValueAnimator and call start() on click" to Compose: creating the animator in the composable body, so every recomposition makes a new one.')
    B(C, S, 2, 'cause', 'Thân composable có thể chạy lại bất cứ lúc nào (chương DC của Runtime); đối tượng tạo ở đó không sống qua các lượt nếu không `remember`.', 'A composable body may run again at any time (Runtime chapter DC); objects created there do not survive passes unless `remember`ed.')
    B(C, S, 2, 'fix', 'Mô tả đích bằng state và dùng `animate*AsState`, hoặc `remember { Animatable(…) }` rồi gọi trong coroutine (C1, C6). [[src:an-value]]', 'Describe the target with state and use `animate*AsState`, or `remember { Animatable(…) }` and call it in a coroutine (C1, C6). [[src:an-value]]')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Đoạn View: `AnimatorSet().apply { playTogether(ObjectAnimator.ofFloat(poster, "alpha", 0f, 1f), ObjectAnimator.ofFloat(poster, "scaleX", 0.8f, 1f)); duration = 500; interpolator = OvershootInterpolator(); start() }`. Viết lại bằng Compose.', 'View code: `AnimatorSet().apply { playTogether(ObjectAnimator.ofFloat(poster, "alpha", 0f, 1f), ObjectAnimator.ofFloat(poster, "scaleX", 0.8f, 1f)); duration = 500; interpolator = OvershootInterpolator(); start() }`. Rewrite it in Compose.')
    B(C, S, 1, 'hint', 'Hai giá trị chạy cùng lúc theo một state → updateTransition (C3). Overshoot: một spring có độ nảy, hoặc easing tự định nghĩa. Đọc trong graphicsLayer.', 'Two values running together from one state → updateTransition (C3). Overshoot: a bouncy spring, or a custom easing. Read in graphicsLayer.')
    B(C, S, 1, 'solkt', 'val shown = remember { MutableTransitionState(false).apply { targetState = true } }\nval t = rememberTransition(shown, label = "poster")\nval alpha by t.animateFloat(transitionSpec = { tween(500) }, label = "a") { if (it) 1f else 0f }\nval scale by t.animateFloat(transitionSpec = { spring(dampingRatio = Spring.DampingRatioMediumBouncy) }, label = "s") { if (it) 1f else 0.8f }\nPoster(Modifier.graphicsLayer { this.alpha = alpha; scaleX = scale })', 'val shown = remember { MutableTransitionState(false).apply { targetState = true } }\nval t = rememberTransition(shown, label = "poster")\nval alpha by t.animateFloat(transitionSpec = { tween(500) }, label = "a") { if (it) 1f else 0f }\nval scale by t.animateFloat(transitionSpec = { spring(dampingRatio = Spring.DampingRatioMediumBouncy) }, label = "s") { if (it) 1f else 0.8f }\nPoster(Modifier.graphicsLayer { this.alpha = alpha; scaleX = scale })')
    B(C, S, 1, 'sol', 'MutableTransitionState(false) với target true chạy ngay khi vào màn hình (chương C3, C4); hai con của một Transition chạy cùng lúc như playTogether; độ "vượt quá" của Overshoot thay bằng spring có độ nảy, nên không trùng từng điểm với bản View.', 'MutableTransitionState(false) with target true runs as soon as it appears (chapters C3, C4); two children of one Transition run together like playTogether; Overshoot\'s overshoot is replaced by a bouncy spring, so it does not match the View version point for point.')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'Ba bước tính mỗi frame của một animator là gì?', 'What are the three per-frame steps of an animator?')
    B(C, S, 1, 'ans', 'Phân số thời gian → TimeInterpolator (phân số đã nội suy) → TypeEvaluator (giá trị).', 'Time fraction → TimeInterpolator (interpolated fraction) → TypeEvaluator (value).')
    B(C, S, 2, 'ask', 'res/anim và res/animator khác nhau thế nào?', 'How do res/anim and res/animator differ?')
    B(C, S, 2, 'ans', 'anim: view animation (tween), chỉ đổi chỗ vẽ; animator: property animator (ValueAnimator, ObjectAnimator, set), đổi thuộc tính thật.', 'anim: view animations (tweens) that only change where things are drawn; animator: property animators (ValueAnimator, ObjectAnimator, set) that change real properties.')
    for q, qv, qe, av, ae, wv, we in [
        ('q1', 'ObjectAnimator khác ValueAnimator ở đâu?', 'How does ObjectAnimator differ from ValueAnimator?', 'Nó tự gọi setter của thuộc tính.', 'It calls the property setter itself.', 'Là lớp con của ValueAnimator, không cần update listener cho một thuộc tính.', 'It is a ValueAnimator subclass and needs no update listener for a single property.'),
        ('q2', 'Thời lượng mặc định của property animation?', 'The default duration of a property animation?', '300 ms.', '300 ms.', 'Theo tài liệu Property Animation.', 'Per the Property Animation docs.'),
        ('q3', 'Trong Compose, cái gì đóng vai TypeEvaluator?', 'In Compose, what plays the role of TypeEvaluator?', 'Cặp TwoWayConverter + AnimationVector.', 'TwoWayConverter + AnimationVector.', 'Chuyển giá trị sang vector số để nội suy (chương C2).', 'They convert values to numeric vectors for interpolation (chapter C2).'),
        ('q4', 'Transition framework làm việc ở mức nào?', 'At what level does the Transition framework work?', 'Cả một ViewGroup.', 'A whole ViewGroup.', 'Animate thay đổi hiển thị hoặc cấu trúc của các con, không phải một View.', 'It animates visibility or structural changes of the children, not a single View.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
